<?php use App\Models\Content;?><main class="gallery"><div class="container"><header class="gallery-intro"><?php if($page['hero_image_id']):?><?=media_img($page['hero_image_id'],$page['title'],'cms-gallery-hero')?><?php endif?><span class="gallery-eyebrow"><?=text('gallery_eyebrow')?></span><h1><?=e($page['hero_heading']?:$page['title'])?></h1><p><?=e($page['subtitle'])?></p></header><nav class="gallery-tabs" aria-label="<?=text('album_label')?>"><?php foreach($albums as $album):?><a href="#album-<?=$album['id']?>" class="gallery-tab"><?=e($album['title'])?></a><?php endforeach?></nav><?php foreach($albums as $album):$items=Content::published('gallery_items','album_id=?',[$album['id']]);?><section id="album-<?=$album['id']?>" class="gallery-panel" aria-labelledby="album-<?=$album['id']?>-heading"><div class="gallery-section-heading"><div><h2 id="album-<?=$album['id']?>-heading"><?=e($album['title'])?></h2><p><?=e($album['description'])?></p></div><?php if($album['profile_url']):?><a class="gallery-follow" href="<?=e(cms_url($album['profile_url']))?>" target="_blank" rel="noopener noreferrer"><?=text('follow_us')?> →</a><?php endif?></div><?php if($items):?><div class="gallery-carousel" role="region" aria-roledescription="carousel" aria-label="<?=e($album['title'])?>"><div class="gallery-grid" id="album-<?=$album['id']?>-track" tabindex="0"><?php foreach($items as $item):$video=media_url($item['video_id'])?:$item['video_url'];$href=$item['permalink']?:($video?:media_url($item['image_id']));?><article class="gallery-card"><a class="gallery-card-link" href="<?=e(cms_url($href?:'#'))?>" <?=$item['permalink']||$video?'target="_blank" rel="noopener noreferrer"':'data-lightbox'?>><div class="gallery-media"><span class="gallery-placeholder"><i class="fa-regular fa-image"></i></span><?=media_img($item['image_id'],$item['title'])?><?php if($video&&(str_ends_with(parse_url($video,PHP_URL_PATH)?:'','.mp4')||$item['video_id'])):?><video class="gallery-preview" data-src="<?=e(cms_url($video))?>" muted loop playsinline preload="none" aria-hidden="true" tabindex="-1"></video><?php endif?><?php if($video):?><span class="gallery-play"><i class="fa-solid fa-play"></i></span><?php endif?></div><div class="gallery-card-body"><h3><?=e($item['title'])?></h3><p class="gallery-caption"><?=e($item['caption'])?></p><span class="gallery-post-link"><?=text($video?'watch_video':'view_post')?> ↗</span></div></a></article><?php endforeach?></div><div class="gallery-controls" hidden><button type="button" data-direction="-1" aria-label="<?=text('previous')?>" aria-controls="album-<?=$album['id']?>-track">←</button><div class="gallery-dots"></div><button type="button" data-direction="1" aria-label="<?=text('next')?>" aria-controls="album-<?=$album['id']?>-track">→</button><span class="visually-hidden gallery-status" aria-live="polite"></span></div></div><?php else:?><div class="gallery-empty"><i class="fa-regular fa-images"></i><p><?=text('gallery_empty')?></p></div><?php endif?></section><?php endforeach?><?php if(!$albums):?><div class="gallery-empty"><p><?=text('gallery_empty')?></p></div><?php endif?><section class="gallery-connect"><span class="gallery-eyebrow"><?=text('stay_connected')?></span><h2><?=text('follow_updates')?></h2><div class="gallery-connect-links"><?php foreach(Content::published('social_links') as $social):?><a class="gallery-follow" href="<?=e(cms_url($social['custom_url']))?>" target="_blank" rel="noopener noreferrer"><i class="<?=e($social['icon'])?>"></i><?=e($social['title'])?></a><?php endforeach?></div></section><?php if($page['body']):?><div class="rich-text"><?=rich($page['body'])?></div><?php endif?></div><?php foreach($sections as $section)cms_view('public/section',compact('section'));?></main><dialog class="cms-lightbox" id="gallery-lightbox"><form method="dialog"><button aria-label="<?=text('gallery_close')?>">×</button></form><img alt=""></dialog>
